ref('frohlichspencer1981transition','Fr{\\\"o}hlich, J{\\\"u}rg and Spencer, Thomas','The {Kosterlitz--Thouless} transition in two-dimensional Abelian spin systems and the {Coulomb} gas',1981,'https://repo-archives.ihes.fr/FONDS_IHES/I_Prepublications/FROHLICH/1981-2002/P_81_25/P_81_25_web.pdf',journal='Communications in Mathematical Physics',volume=81,pages='527--602',doi='10.1007/BF01208273',annote='Full IHES/P/81/25 preprint opened; Section 7, Theorem 7.3 and remarks read. Publisher metadata confirms received 23 April 1981 and December 1981 publication. The logarithmic lower bound is distinguished from the separate infrared upper bound.')
ref('frohlichpfisterspencer1982surfaces','Fr{\\\"o}hlich, J{\\\"u}rg and Pfister, C. E. and Spencer, Thomas','On the Statistical Mechanics of Surfaces',1982,'https://www.numdam.org/item/RCP25_1982__30__84_0.pdf',journal="Les rencontres physiciens-math\\'ematiciens de Strasbourg--RCP25",volume=30,pages='84--114',annote='Full primary lecture notes read, Sections 2--4, Theorems 4 and 6, and three distinct ensembles in Section 3. IHES/P/82/20 version also opened; exact day of circulation not found. The text explicitly separates SOS, self-avoiding, planar and branched surfaces.')
ref('durhuusfrohlichjonsson1983surfaces','Durhuus, Bergfinnur and Fr{\\\"o}hlich, J{\\\"u}rg and J{\\\'o}nsson, Thordur','Self-avoiding and planar random surfaces on the lattice',1983,'https://iris.hi.is/en/publications/self-avoiding-and-planar-random-surfaces-on-the-lattice/',journal='Nuclear Physics B',volume=225,number=2,pages='185--203',doi='10.1016/0550-3213(83)90048-2',annote='Author institutional metadata and complete abstract opened. Publication 31 October 1983; exact preprint date not verified. Exponential growth with o(area), boundary-independent rate and finite correlation length are stated. Publisher full paper blocked; no full-proof verification claimed.')
